import { useEffect, useState } from 'react';
import { useNavigate, useParams } from 'react-router-dom';
import { Bilingual } from '@/components/ui/Bilingual.js';
import { Button } from '@/components/ui/Button.js';
import { Spinner } from '@/components/ui/Spinner.js';
import { share as shareApi } from '@/api/endpoints.js';
import { isApiError } from '@/api/errors.js';
import { useAuth } from '@/features/auth/session.js';
import { useSync } from '@/sync/store.js';
import { getActiveNotebook, listNotebooks, setActiveNotebook } from '@/db/repo.js';
import type { StoredNotebook } from '@/db/schema.js';
import { ProOffer } from '@/features/billing/ProOffer.js';
import { offerable, useBilling } from '@/features/billing/state.js';
import { LANGUAGE_NAMES } from '@/features/settings/data.js';
import { t } from '@/i18n/index.js';
import { useLiveQuery } from '@/lib/useLiveQuery.js';
import type { ApiSharedNotebook } from '@/api/types.js';
import styles from './SharedNotebook.module.css';

type State = { kind: 'loading' } | { kind: 'gone' } | { kind: 'ready'; notebook: ApiSharedNotebook };

/** What the last tap came to. */
type Outcome =
  | { kind: 'added'; into: StoredNotebook; added: number; skipped: number }
  | { kind: 'needsPro' }
  | { kind: 'failed'; message: string };

/**
 * The learner's notebooks the shared words can go into: theirs to edit, in
 * the same two languages, the one the app is showing first. A copy into a
 * notebook of other languages would put meanings in the wrong language,
 * which the server refuses too (409 `languages_differ`).
 */
async function matchingNotebooks(
  targetLang: string,
  meaningLang: string,
): Promise<{ list: StoredNotebook[]; active: string | undefined }> {
  const [all, active] = await Promise.all([listNotebooks(), getActiveNotebook()]);
  const same = (a: string, b: string): boolean => a.toLowerCase() === b.toLowerCase();
  const list = all.filter(
    (notebook) =>
      notebook.role !== 'viewer' &&
      same(notebook.targetLang, targetLang) &&
      same(notebook.meaningLang, meaningLang),
  );
  const first = list.find((notebook) => notebook.id === active?.id);
  return {
    list: first === undefined ? list : [first, ...list.filter((one) => one !== first)],
    active: active?.id,
  };
}

/**
 * The name a copy takes.
 *
 * Whatever it was shared as, unless the account already has a notebook by
 * that name — two notebooks called "English" in the picker are two rows
 * nobody can tell apart, and a copy is exactly the case where that happens.
 */
async function nameFor(shared: string): Promise<string> {
  const title = shared.trim();
  const taken = (await listNotebooks()).some((notebook) => notebook.title.trim() === title);
  return taken ? t('shared.copyTitle', { title }) : title;
}

/**
 * A shared notebook, read by anyone at all.
 *
 * This is the one screen in Lexpad that works with no account, so it is
 * written for a stranger: what these words are, whose language pair they
 * are in, and one thing to do about them. It reads from the network rather
 * than from IndexedDB, which is the one place that rule cannot hold —
 * these are not this device's words, and there is nothing local to render.
 */
export function SharedNotebook(): React.JSX.Element {
  const { shareId = '' } = useParams();
  const navigate = useNavigate();
  const signedIn = useAuth((state) => state.status) === 'ready';
  const [state, setState] = useState<State>({ kind: 'loading' });
  const [taking, setTaking] = useState<'copy' | 'add' | undefined>();
  const [outcome, setOutcome] = useState<Outcome | undefined>();
  const [chosen, setChosen] = useState<string | undefined>();
  const billing = useBilling((s) => s.state);
  const billingChecked = useBilling((s) => s.checked);
  const shared = state.kind === 'ready' ? state.notebook : undefined;
  const matches = useLiveQuery(
    async () =>
      signedIn && shared !== undefined
        ? matchingNotebooks(shared.targetLang, shared.meaningLang)
        : { list: [], active: undefined },
    null,
    [signedIn, shared?.targetLang, shared?.meaningLang],
  );
  const into = matches?.list.find((notebook) => notebook.id === chosen) ?? matches?.list[0];

  useEffect(() => {
    let live = true;
    shareApi
      .open(shareId)
      .then((notebook) => {
        if (live) setState({ kind: 'ready', notebook });
      })
      .catch(() => {
        if (live) setState({ kind: 'gone' });
      });
    return () => {
      live = false;
    };
  }, [shareId]);

  const signIn = (): void => {
    // Somebody with no account is sent to sign in and brought back here,
    // rather than having a notebook made for an account that does not
    // exist yet. The copy stays their own deliberate tap.
    void navigate('/auth', { state: { from: `/s/${shareId}` } });
  };

  /**
   * "Add to my notebook": into one the learner keeps, in the same languages.
   * It makes no notebook, so it is open on every plan. What came of it is
   * said in numbers the server counted, and the notebook is one tap away.
   */
  const add = (): void => {
    if (into === undefined) return;
    setTaking('add');
    setOutcome(undefined);
    shareApi
      .addTo(into.id, shareId)
      .then((result) => {
        setOutcome({ kind: 'added', into, added: result.added, skipped: result.skipped });
        // The words were written on the server; this device has them once it pulls.
        void useSync.getState().syncNow();
      })
      .catch((cause: unknown) => {
        setOutcome({ kind: 'failed', message: failureOf(cause) });
      })
      .finally(() => {
        setTaking(undefined);
      });
  };

  const open = (notebook: StoredNotebook): void => {
    setTaking('add');
    void useSync
      .getState()
      .syncNow()
      .then(() => setActiveNotebook(notebook.id))
      .then(() => navigate('/notebook'));
  };

  const take = (): void => {
    if (!signedIn) {
      signIn();
      return;
    }
    setTaking('copy');
    setOutcome(undefined);
    void nameFor(state.kind === 'ready' ? state.notebook.title : '')
      .then((title) => shareApi.copy(shareId, title))
      .then(async (made) => {
        // The words are written on the server, so this device only has
        // them once it has pulled; opening the notebook first would show
        // an empty one. The copy then becomes the notebook the app is
        // showing, because arriving at somebody else's words and being
        // put back in front of your own would be the app ignoring what
        // you just did. Settings is where you switch back.
        await useSync.getState().syncNow();
        await setActiveNotebook(made.id);
        void navigate('/notebook');
      })
      .catch((cause: unknown) => {
        setTaking(undefined);
        // A notebook of its own is part of Pro once there is one already;
        // the server is the one that knows, and its refusal is the moment
        // to say so. Adding to the notebook they keep stays open beside it.
        setOutcome(
          isApiError(cause, 'needsPayment')
            ? { kind: 'needsPro' }
            : { kind: 'failed', message: failureOf(cause) },
        );
      });
  };

  if (state.kind === 'loading') {
    return (
      <main className={styles.screen}>
        <div className={styles.centre}>
          <Spinner />
          <p className={styles.note}>{t('shared.loading')}</p>
        </div>
      </main>
    );
  }

  if (state.kind === 'gone') {
    return (
      <main className={styles.screen}>
        <div className={styles.centre}>
          <h1 className={styles.goneTitle}>{t('shared.gone')}</h1>
          <p className={styles.note}>{t('shared.goneBody')}</p>
          <Button
            variant="secondary"
            onClick={() => {
              void navigate('/');
            }}
          >
            {t('shared.madeWith')}
          </Button>
        </div>
      </main>
    );
  }

  const { notebook } = state;
  const target = notebook.targetLang;
  const meaning = notebook.meaningLang;

  return (
    <main className={styles.screen}>
      <header className={styles.head}>
        <h1 className={styles.title} dir="auto">
          {notebook.title}
        </h1>
        <p className={styles.sub}>
          {notebook.wordCount === 1 ? t('shared.wordsOne') : t('shared.words', { count: notebook.wordCount })}
          {' · '}
          {t('shared.pair', {
            target: LANGUAGE_NAMES[target],
            meaning: LANGUAGE_NAMES[meaning],
          })}
        </p>
        {notebook.words.length < notebook.wordCount && (
          <p className={styles.note}>{t('shared.showing', { count: notebook.words.length })}</p>
        )}
      </header>

      <ol className={styles.list}>
        {notebook.words.map((word, index) => {
          const first = word.meanings?.[0];
          const example = first?.examples?.[0];
          return (
            <li key={`${word.headword ?? ''}-${index}`} className={styles.row}>
              <Bilingual lang={target} className={styles.headword} block>
                {word.headword}
              </Bilingual>
              {first?.meaning !== undefined && first.meaning !== '' && (
                <Bilingual lang={meaning} className={styles.meaning} block>
                  {first.meaning}
                </Bilingual>
              )}
              {example?.sentence !== undefined && example.sentence !== '' && (
                <Bilingual lang={target} className={styles.example} block>
                  {example.sentence}
                </Bilingual>
              )}
            </li>
          );
        })}
      </ol>

      <p className={styles.about}>{t('shared.about')}</p>

      {/* The one thing to do, always reachable: it follows the page down
          rather than waiting at the bottom of a long list. */}
      <div className={styles.bar}>
        <div className={styles.barInner}>
          {outcome?.kind === 'failed' && (
            <p className={styles.failed} role="alert">
              {outcome.message}
            </p>
          )}
          {outcome?.kind === 'needsPro' && (
            <ProOffer occasion="notebook" about={{ targetLang: target, meaningLang: meaning }} />
          )}
          {/* Where no offer can be made, the fact still is: plainly, once
              the plan is known. */}
          {outcome?.kind === 'needsPro' && billingChecked && !offerable(billing, target, meaning) && (
            <p className={styles.failed} role="alert">
              {t('pro.notebook.title')}
            </p>
          )}
          {outcome?.kind === 'added' ? (
            <>
              <p className={styles.done} role="status">
                {outcome.added === 0
                  ? t('shared.addedNone', { title: outcome.into.title })
                  : t('shared.added', { count: outcome.added, title: outcome.into.title })}
                {outcome.skipped > 0 && <> {t('shared.skipped', { count: outcome.skipped })}</>}
              </p>
              <Button
                block
                size="large"
                busy={taking === 'add'}
                onClick={() => {
                  open(outcome.into);
                }}
              >
                {t('shared.open', { title: outcome.into.title })}
              </Button>
            </>
          ) : !signedIn ? (
            <Button block size="large" onClick={signIn}>
              {t('shared.takeSignedOut')}
            </Button>
          ) : into !== undefined ? (
            <>
              {matches !== null && matches.list.length > 1 && (
                <div className={styles.choose} role="radiogroup" aria-label={t('shared.into')}>
                  {matches.list.map((notebook) => (
                    <label key={notebook.id} className={styles.choice}>
                      <input
                        type="radio"
                        name="into"
                        checked={notebook.id === into.id}
                        onChange={() => {
                          setChosen(notebook.id);
                        }}
                      />
                      <span dir="auto">{notebook.title}</span>
                    </label>
                  ))}
                </div>
              )}
              <Button
                block
                size="large"
                busy={taking === 'add'}
                disabled={taking !== undefined}
                onClick={add}
              >
                {taking === 'add'
                  ? t('shared.adding')
                  : matches !== null && matches.list.length > 1
                    ? t('shared.addTo', { title: into.title })
                    : t('shared.addToMine')}
              </Button>
              <Button
                block
                variant="ghost"
                busy={taking === 'copy'}
                disabled={taking !== undefined}
                onClick={take}
              >
                {taking === 'copy' ? t('shared.taking') : t('shared.takeAsNew')}
              </Button>
            </>
          ) : (
            <Button block size="large" busy={taking === 'copy'} disabled={matches === null} onClick={take}>
              {taking === 'copy' ? t('shared.taking') : t('shared.take')}
            </Button>
          )}
          <p className={styles.fine}>{t('shared.mine')}</p>
        </div>
      </div>
    </main>
  );
}

/** A refusal in the learner's own words, never the server's codes. */
function failureOf(cause: unknown): string {
  if (isApiError(cause, 'offline')) return t('shared.offline');
  if (isApiError(cause, 'conflict') && cause.code === 'languages_differ') return t('shared.languagesDiffer');
  if (isApiError(cause, 'forbidden')) return t('shared.notYours');
  if (isApiError(cause, 'notFound')) return t('shared.goneBody');
  return t('shared.takeFailed');
}
